    expect(judged).toEqual([["numericUndeclared", "/snapshot/width"], ["labelAbsent", "/snapshot/plantedKey"]]);
    const controls = mutationInputControls(mutationInputAudit(entry.schema, (id) => documents.get(id)).inputs);
